void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Aggressive rephasing of variable polarity
    int r = rand() % 100;
    if (r < 50) {
        // Use the best local assignment found so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 70) {
        // Invert the best local assignment
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // Random polarity
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // Optionally reset restart counter to avoid premature next restart
    restarts = 0;
}
